style.css:
@-moz-document domain("hianimez.is") {
body {
    background-color: #0e0e0e !important;
    color: #e0e0e0 !important;
    font-family: 'Segoe UI', sans-serif !important;
  }

  header, nav, footer, .navbar, .header, .footer {
    background-color: #141414 !important;
    border-bottom: 1px solid #00ffff !important;
  }

  a, a:visited {
    color: #00ffff !important;
    transition: color 0.3s ease;
  }

  a:hover {
    color: #00bcd4 !important;
  }

  .button, button, input[type="button"], input[type="submit"] {
    background-color: #00ffff !important;
    color: #0e0e0e !important;
    border: none !important;
    border-radius: 5px !important;
    transition: all 0.3s ease;
  }

  .button:hover, button:hover, input[type="button"]:hover, input[type="submit"]:hover {
    background-color: #00bcd4 !important;
    color: #ffffff !important;
  }

  .card, .anime-card, .content-box, .episode-list {
    background-color: #1a1a1a !important;
    border: 1px solid #00ffff40 !important;
    box-shadow: 0 0 5px #00ffff40 !important;
    border-radius: 10px !important;
  }

  .popup, .modal, .dropdown-menu {
    background-color: #1a1a1a !important;
    color: #e0e0e0 !important;
  }
}
